// === Tab: mySketch.js ===
/* Created for #WCCChallenge "As Above, So Below"

Birbs: I found a cool spiral tunnel on shadertoy and that prompted me to wonder whether it was possible to spiral image pixels. 
I am not sure whether the pixels are truely spirally out, but I still think the effect is still cool. Since I wanted to try to keep 
to the prompt, I added N/S symmetry using the kaleidoscopeSDF from Lygia.

The first two versions are my own, but I also asked chatGPT to edit my spiral frag code to morph between a globe 
and the flat spiral (visually morphing from a view "above" to "below"). 

The images are mine.

https://github.com/patriciogonzalezvivo/lygia
https://www.shadertoy.com/view/MdcGWl
*/

let imgs = ["sky3.jpg", "pink.jpg", "rocks.jpg", "coral.jpg"]
let myShader, img, canvas;
let images = [];

let params = {
	transform: "Kaleidoscope",
	i: 0
}

async function setup() {
	let canvasSize = max(windowWidth, windowHeight);
	canvas = createCanvas(canvasSize, canvasSize, WEBGL);
	canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);

	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);
	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});
	gui.add(params, "i", 0, 3, 1).name("Change image")
		.onChange(() => updateImage())
	gui.add(params, "transform", ["Kaleidoscope", "Spiral", "Globe"]).name("Image Transformation").
		onChange(() => chooseTransform())

	for (let img of imgs) {
		images.push(await loadImage(img))
	}

	updateImage()

	noStroke();
	chooseTransform()
}
function updateImage() {
	switch (params.i) {
		case 0:
			img = images[0];
			break;
		case 1:
			img = images[1];
			break;
		case 2:
			img = images[2];
			break;
		case 3:
			img = images[3];
			break;
	}
}


async function chooseTransform() {
	switch (params.transform) {
		case "Kaleidoscope":
			pixelDensity(2);
			myShader = await createShader(resolveLygia(vert), resolveLygia(kaleidoscopeFrag));
			break
		case "Spiral":
			pixelDensity(2);
			myShader = await createShader(resolveLygia(vert), resolveLygia(spiralFrag));
			break;
		case "Globe":
			pixelDensity(1)
			myShader = await createShader(resolveLygia(vert), resolveLygia(globeFrag));
			break;
	}
}

function draw() {

	myShader.setUniform("u_resolution", [width, height]);
	myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	myShader.setUniform("u_time", millis() / 1000.0);
	myShader.setUniform("u_tex", img);
	myShader.setUniform("u_morph", 0.5 + 0.5 * sin(millis() * 0.0003));
	// let m = constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, 0, 1);
	//   myShader.setUniform("u_morph", 0.5 + 0.5*m);

	myShader.setUniform("iFrame", frameCount);
	shader(myShader);

	rect(0, 0, width, height);
}

const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`;

const kaleidoscopeFrag = `#version 300 es
precision highp float;
out vec4 O;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

uniform float iTimeDelta;
uniform sampler2D u_tex;

#include "lygia/generative/curl.glsl"
#include "lygia/generative/worley.glsl"
#include "lygia/sdf.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/math/const.glsl"
#include "lygia/color/blend.glsl"
#include "lygia/space/kaleidoscope.glsl"

void main()
{
   vec2 pixel = gl_FragCoord.xy/u_resolution.xy;
	pixel = pixel*0.5; // I increased pixel density, so I am offsetting to account for this
   float s = spiralSDF(pixel, 0.6);

   pixel.x += u_time * 0.1; // switch to pixels moving horizontally to get N/S symmetry
   // pixel.y += u_time * 0.25;

   vec2 k = kaleidoscope(pixel, 2.0, 0.5);
   vec2 w = worley2(k + s);
   vec4 col = texture(u_tex, w);

   O = col;
}`;

const spiralFrag = `#version 300 es
precision highp float;
out vec4 O;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

uniform float iTimeDelta;
uniform sampler2D u_tex;

#include "lygia/generative/curl.glsl"
#include "lygia/generative/worley.glsl"
#include "lygia/sdf.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/math/const.glsl"
#include "lygia/color/blend.glsl"

void main()
{
   vec2 pixel = gl_FragCoord.xy/u_resolution.xy;
	pixel = pixel*0.5; // I increased pixel density, so I am offsetting to account for this
   float s = spiralSDF(pixel, 0.6);

   pixel.y += u_time * 0.1;

   vec2 w0 = worley2(pixel + s);
   vec2 w1 = worley2(pixel - s);

   vec2 w = mix(w0, w1, 0.5);

  vec4 col = texture(u_tex, w);

   O = col;
}`;


// Adapted by chatGPT from my spiralFrag code
const globeFrag = `#version 300 es
precision highp float;

out vec4 O;

uniform vec2  u_resolution;
uniform float u_time;
uniform float u_morph;   // <<< morph control
uniform sampler2D u_tex;

#include "lygia/sdf.glsl"
#include "lygia/generative/worley.glsl"
#include "lygia/math/const.glsl"

void main() {
    // Screen UVs
    vec2 uv = gl_FragCoord.xy / u_resolution.xy;
    vec2 p  = uv * 2.0 - 1.0;
    p.x *= u_resolution.x / u_resolution.y;

    // FLAT spiral UVs (your original space)
    vec2 flatUV = uv;
    flatUV.y += u_time * 0.1;

    //GLOBE spiral UVs (spherical mapping)

    float r = length(p);

    // Disc mask for globe
    float globeMask = smoothstep(1.0, 0.98, r);

    // Sphere normal
    float z = sqrt(max(0.0, 1.0 - r * r));
    vec3 n = normalize(vec3(p, z));

    vec2 globeUV;
    globeUV.x = atan(n.x, n.z) / TAU + 0.5;
    globeUV.y = asin(n.y) / PI  + 0.5;
    globeUV.y += u_time * 0.25;

    vec2 spiralUV = mix(flatUV, globeUV, u_morph);

    // Spiral + Worley (unchanged logic)

    float s = spiralSDF(spiralUV, 0.6);

    vec2 w0 = worley2(spiralUV + s);
    vec2 w1 = worley2(spiralUV - s);
    vec2 w  = mix(w0, w1, 0.5);

    vec4 col = texture(u_tex, w);


    // Lighting fades in with globe

    float facing = clamp(n.z, 0.0, 1.0);
    float lighting = mix(1.0, mix(0.7, 1.15, facing), u_morph);

    col.rgb *= lighting;

    // Fade edges only when globe is active
    col.a *= mix(1.0, globeMask, u_morph);

    O = col;
}`

